#include <bits/stdc++.h>
using namespace std;

int sumSubarrayMins(vector<int>& arr) {
    int n = arr.size();
    const long long MOD = 1e9 + 7;
    vector<int> prevS(n, -1), nextS(n, n);
    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && arr[st.top()] > arr[i]) st.pop();
        if (!st.empty()) prevS[i] = st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && arr[st.top()] >= arr[i]) st.pop();
        if (!st.empty()) nextS[i] = st.top();
        st.push(i);
    }
    long long ans = 0;
    for (int i = 0; i < n; ++i)
        ans = (ans + (long long)(i - prevS[i]) * (nextS[i] - i) % MOD * arr[i]) % MOD;
    return (int)ans;
}

