import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        final long MOD = 1_000_000_007L;
        int[] prevS = new int[n], nextS = new int[n];
        java.util.Arrays.fill(prevS, -1);
        java.util.Arrays.fill(nextS, n);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; ++i) {
            while (!stack.isEmpty() && arr[stack.peek()] > arr[i]) stack.pop();
            if (!stack.isEmpty()) prevS[i] = stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) stack.pop();
            if (!stack.isEmpty()) nextS[i] = stack.peek();
            stack.push(i);
        }
        long ans = 0;
        for (int i = 0; i < n; ++i)
            ans = (ans + (long)(i - prevS[i]) * (nextS[i] - i) % MOD * arr[i]) % MOD;
        return (int) ans;
    }
}
